package com.cpf.batch.control.deploy; import com.cpf.batch.api.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.UUID;
@RestController @RequestMapping("/api/v1/batch/deployment-plans") public class DeploymentPlanController { private final DeploymentPlanRepository plans;private final DeploymentEngine engine;public DeploymentPlanController(DeploymentPlanRepository p,DeploymentEngine e){plans=p;engine=e;}@PostMapping ResponseEntity<DeploymentPlanRepository.Plan> plan(@RequestBody PlanRequest r)throws Exception{String id=r.planId()==null||r.planId().isBlank()?UUID.randomUUID().toString():r.planId();return ResponseEntity.status(201).body(plans.create(id,r.manifest(),r.requestedBy(),r.reason()));}@PostMapping("/{id}/execute-approved") ResponseEntity<DeploymentResult> execute(@PathVariable String id,@RequestBody ApprovedExecution a)throws Exception{DeploymentRequest r=req(id,a);DeploymentResult x=engine.deploy(r);plans.mark(id,x.state().name());return ResponseEntity.accepted().body(x);}@PostMapping("/{id}/rollback-approved") ResponseEntity<DeploymentResult> rollback(@PathVariable String id,@RequestBody ApprovedExecution a)throws Exception{DeploymentRequest r=req(id,a);DeploymentResult x=engine.rollbackApproved(r);plans.mark(id,x.state().name());return ResponseEntity.accepted().body(x);}private DeploymentRequest req(String id,ApprovedExecution a)throws Exception{return new DeploymentRequest(a.commandRequestId(),a.commandRequestId(),plans.load(id),a.expectedVersion(),a.requestedBy(),a.reason(),Long.toString(a.approvalRequestId()),a.approvedBy(),Instant.now().plusSeconds(900));}public record PlanRequest(String planId,DeploymentCellManifest manifest,String requestedBy,String reason){}public record ApprovedExecution(long approvalRequestId,String commandRequestId,long expectedVersion,String requestedBy,String approvedBy,String reason){} }
